def compute(vars):
    flight_attendants = vars["v1"]
    pilots = vars["v2"]

    if pilots == 0:
        return None

    value = flight_attendants / pilots
    return {
        "value": value,
        "trace": {
            "flight_attendants": flight_attendants,
            "pilots": pilots,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio",
            },
        },
    }
